WITH left_oracle AS (SELECT mktcode,tgtcode,bizdate FROM `newzl`.`hsj_stock_hq_basic_technical` WHERE bizdate='2026-04-14' AND ABS(ma5-ma20)/NULLIF(GREATEST(ABS(ma5),ABS(ma20)),0)<=0.03), right_oracle AS (WITH w AS (SELECT mktcode,tgtcode,bizdate,ma5,ma20,LAG(ma5) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS p5,LAG(ma20) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate) AS p20 FROM `newzl`.`hsj_stock_hq_basic_technical`) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND ma5>ma20 AND p5<=p20), left_filtered AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM left_oracle o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=1 AND q.volume>=100), right_filtered AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM right_oracle o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE 1=1 AND q.volume>=10) SELECT mktcode,tgtcode,bizdate FROM left_filtered UNION DISTINCT SELECT mktcode,tgtcode,bizdate FROM right_filtered;
